        .recu-footer p {
            font-size: 11px;
            color: #94a3b8;
            margin: 0;
            line-height: 1.6;
        }

        /* ===================== PRINT STYLES ===================== */
        @media print {
            body { background: #fff !important; }
            .recu-topbar,
            .recu-actions,
            .no-print { display: none !important; }
            .recu-page { min-height: unset; }
            .recu-wrapper { padding: 0; }
            .recu-doc {
                max-width: 100%;
                box-shadow: none;
                border-radius: 0;
            }
            .recu-header {
                -webkit-print-color-adjust: exact;
                print-color-adjust: exact;
                color-adjust: exact;
            }
            @page { margin: 12mm; size: A4; }
        }
    </style>
</head>
<body>
<div class="recu-page">

    <!-- Top navigation bar (hidden when printing) -->
    <div class="recu-topbar no-print">
        <a href="{% url 'payments:liste' %}" class="btn btn-sm btn-outline-secondary">
            <i class="bi bi-arrow-left me-1"></i>Retour
        </a>
        <span class="text-muted small fw-medium">Reçu de paiement</span>
        <div class="recu-actions">
            <button onclick="window.print()" class="btn btn-sm btn-outline-secondary">
                <i class="bi bi-printer me-1"></i>Imprimer
            </button>
            <button onclick="downloadPDF()" class="btn btn-sm btn-primary">
                <i class="bi bi-file-earmark-pdf me-1"></i>Télécharger PDF
            </button>
        </div>
    </div>

    <div class="recu-wrapper">
        <div class="recu-doc" id="recuDoc">

            <!-- Header -->
            <div class="recu-header">
                <div class="recu-header-top">
                    <div class="recu-school">
                        <div class="recu-logo-wrap">
                            <img src="{% static 'img/logo-ecole.svg' %}" alt="Logo" width="40" height="40">
                        </div>
                        <div class="recu-school-name">
                            <div class="recu-school-main">Lycée Étoile Brillante</div>
                            <div class="recu-school-sub">Plateforme numérique</div>
                        </div>
                    </div>
                    <div class="recu-badge">
                        {% if paiement.statut == "paye" %}✓ Confirmé{% elif paiement.statut == "en_attente" %}⏳ En attente{% else %}✕ Échec{% endif %}
                    </div>
                </div>
                <div class="recu-title-row">
                    <div class="recu-title">Reçu de paiement</div>
                    <div class="recu-amount-big">${{ paiement.montant|floatformat:2 }}</div>
                </div>
            </div>

            <!-- Body -->
            <div class="recu-body">

                <!-- Élève -->
                <div class="recu-section-label">Informations de l'élève</div>
                <div class="recu-row">
                    <span class="recu-row-label">Nom complet</span>
                    <span class="recu-row-value">{{ eleve.nom_complet }}</span>
                </div>
                <div class="recu-row">
                    <span class="recu-row-label">Identifiant scolaire</span>
                    <span class="recu-row-value" style="font-family:monospace;font-size:12px;">{{ eleve.user.identifiant }}</span>
                </div>
                {% if eleve.classe %}
                <div class="recu-row">
                    <span class="recu-row-label">Classe</span>
                    <span class="recu-row-value">{{ eleve.classe }}</span>
                </div>
                {% endif %}

                <div class="recu-divider"></div>

                <!-- Paiement -->
                <div class="recu-section-label">Détails du paiement</div>
                <div class="recu-row">
                    <span class="recu-row-label">Description</span>
                    <span class="recu-row-value">{{ paiement.description|default:"—" }}</span>
                </div>
                {% if paiement.frais %}
                <div class="recu-row">
                    <span class="recu-row-label">Frais</span>
                    <span class="recu-row-value">{{ paiement.frais }}</span>
                </div>
                {% endif %}
                {% if paiement.moyen_paiement %}
                <div class="recu-row">
                    <span class="recu-row-label">Moyen de paiement</span>
                    <span class="recu-row-value">{{ paiement.get_moyen_paiement_display }}</span>
                </div>
                {% endif %}
                <div class="recu-row">
