   279→    padding: 6px;
   280→    border-radius: 6px;
   281→    transition: background .15s, color .15s;
   282→    line-height: 1;
   283→    flex-shrink: 0;
   284→}
   285→.topbar-toggle:hover { background: var(--bg); color: var(--text); }
   286→.topbar-breadcrumb {
   287→    display: flex;
   288→    align-items: center;
   289→    gap: 6px;
   290→    flex: 1;
   291→    min-width: 0;
   292→}
   293→.breadcrumb-item {
   294→    font-size: 13px;
   295→    color: var(--text-3);
   296→    white-space: nowrap;
   297→}
   298→.breadcrumb-item.current {
   299→    font-weight: 600;
   300→    color: var(--text);
   301→}
   302→.breadcrumb-sep { color: var(--text-3); font-size: 12px; }
   303→.topbar-right {
   304→    display: flex;
   305→    align-items: center;
   306→    gap: 10px;
   307→    flex-shrink: 0;
   308→}
   309→.topbar-badge {
   310→    display: flex;
   311→    align-items: center;
   312→    gap: 6px;
   313→    padding: 5px 12px;
   314→    background: var(--accent-light);
   315→    border-radius: 20px;
   316→    font-size: 12px;
   317→    color: var(--accent);
   318→    font-weight: 600;
   319→}
   320→
   321→/* ===================== CONTENT ===================== */
   322→.admin-content { flex: 1; padding: 24px; }
   323→
   324→.page-header {
   325→    display: flex;
   326→    align-items: flex-end;
   327→    justify-content: space-between;
   328→    gap: 12px;
   329→    margin-bottom: 24px;
   330→    flex-wrap: wrap;
   331→}
   332→.page-header-left {}
   333→.page-title {
   334→    font-size: 20px;
   335→    font-weight: 700;
   336→    color: var(--text);
   337→    margin: 0;
   338→    line-height: 1.3;
   339→}
   340→.page-subtitle {
   341→    font-size: 13px;
   342→    color: var(--text-2);
   343→    margin: 3px 0 0;
   344→}
   345→
   346→/* ===================== STAT CARDS ===================== */
   347→.stat-grid {
   348→    display: grid;
   349→    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
   350→    gap: 16px;
   351→    margin-bottom: 24px;
   352→}
   353→
   354→.stat-card {
   355→    background: var(--surface);
   356→    border: 1px solid var(--border);
   357→    border-radius: var(--radius);
   358→    padding: 20px;
   359→    display: flex;
   360→    flex-direction: column;
   361→    gap: 12px;
   362→    transition: box-shadow .2s, transform .2s;
   363→    position: relative;
   364→    overflow: hidden;
   365→}
   366→.stat-card:hover { box-shadow: var(--shadow-md); transform: translateY(-1px); }
   367→.stat-card::after {
   368→    content: "";
   369→    position: absolute;
   370→    top: 0; left: 0; right: 0;
   371→    height: 3px;
   372→    background: var(--card-accent, var(--accent));
   373→    border-radius: var(--radius) var(--radius) 0 0;
   374→}
   375→.stat-card.blue   { --card-accent: #3b82f6; }
   376→.stat-card.green  { --card-accent: #16a34a; }
   377→.stat-card.orange { --card-accent: #f59e0b; }
   378→.stat-card.red    { --card-accent: #ef4444; }
   379→.stat-card.purple { --card-accent: #7c3aed; }
   380→.stat-card.teal   { --card-accent: #0d9488; }
   381→
   382→.stat-row {
   383→    display: flex;
   384→    align-items: center;
   385→    justify-content: space-between;
   386→}
   387→.stat-icon {
   388→    width: 44px;
   389→    height: 44px;
   390→    border-radius: 10px;
   391→    display: flex;
   392→    align-items: center;
   393→    justify-content: center;
   394→    font-size: 20px;
   395→    flex-shrink: 0;
   396→}
   397→.stat-card.blue   .stat-icon { background: #dbeafe; color: #2563eb; }
   398→.stat-card.green  .stat-icon { background: var(--success-bg); color: var(--success); }
   399→.stat-card.orange .stat-icon { background: var(--warning-bg); color: var(--warning); }
   400→.stat-card.red    .stat-icon { background: var(--danger-bg); color: var(--danger); }
   401→.stat-card.purple .stat-icon { background: var(--purple-bg); color: var(--purple); }
   402→.stat-card.teal   .stat-icon { background: var(--teal-bg); color: var(--teal); }
   403→
   404→.stat-value {
   405→    font-size: 26px;
   406→    font-weight: 800;
   407→    color: var(--text);
   408→    line-height: 1;
   409→}
   410→.stat-label {
   411→    font-size: 12px;
   412→    color: var(--text-2);
   413→    font-weight: 500;
   414→    margin-top: 3px;
   415→}
   416→.stat-trend {
   417→    font-size: 11px;
   418→    color: var(--text-3);
   419→    display: flex;
   420→    align-items: center;
   421→    gap: 3px;
   422→}
   423→
   424→/* ===================== FINANCE CARDS ===================== */
   425→.finance-grid {
   426→    display: grid;
   427→    grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
   428→    gap: 16px;
   429→    margin-bottom: 24px;
   430→}
   431→
   432→.finance-card {
   433→    background: var(--surface);
   434→    border: 1px solid var(--border);
   435→    border-radius: var(--radius);
   436→    padding: 20px 22px;
   437→    display: flex;
   438→    align-items: center;
   439→    gap: 16px;
   440→    transition: box-shadow .2s;
   441→}
   442→.finance-card:hover { box-shadow: var(--shadow); }
   443→.finance-icon {
   444→    width: 52px;
   445→    height: 52px;
   446→    border-radius: 14px;
   447→    display: flex;
   448→    align-items: center;
   449→    justify-content: center;
   450→    font-size: 22px;
   451→    flex-shrink: 0;
   452→}
   453→.finance-icon.green  { background: var(--success-bg); color: var(--success); }
   454→.finance-icon.orange { background: var(--warning-bg); color: var(--warning); }
   455→.finance-icon.red    { background: var(--danger-bg); color: var(--danger); }
   456→.finance-body {}
   457→.finance-value {
   458→    font-size: 22px;
   459→    font-weight: 800;
   460→    line-height: 1.2;
   461→}
   462→.finance-value.green  { color: var(--success); }
   463→.finance-value.orange { color: var(--warning); }
   464→.finance-value.red    { color: var(--danger); }
   465→.finance-label {
   466→    font-size: 12px;
   467→    color: var(--text-2);
   468→    margin-top: 2px;
   469→}
   470→
   471→/* ===================== CARDS ===================== */
   472→.admin-card {
   473→    background: var(--surface);
   474→    border: 1px solid var(--border);
   475→    border-radius: var(--radius);
   476→    overflow: hidden;
   477→    box-shadow: var(--shadow-sm);
   478→}
   479→.admin-card + .admin-card { margin-top: 16px; }
   480→
   481→.admin-card-header {
   482→    padding: 14px 18px;
   483→    border-bottom: 1px solid var(--border);
   484→    display: flex;
   485→    align-items: center;
   486→    justify-content: space-between;
   487→    gap: 8px;
   488→    background: var(--surface);
   489→}
   490→.admin-card-header h6 {
   491→    font-size: 13.5px;
   492→    font-weight: 700;
   493→    color: var(--text);
   494→    margin: 0;
   495→    display: flex;
   496→    align-items: center;
   497→    gap: 7px;
   498→}
   499→.admin-card-header h6 i { color: var(--accent); }
   500→.admin-card-body { padding: 16px 18px; }
   501→
   502→/* ===================== TABLES ===================== */
   503→.admin-table {
   504→    width: 100%;
   505→    border-collapse: collapse;
   506→    font-size: 13px;
   507→}
   508→.admin-table thead th {
   509→    font-size: 11px;
   510→    font-weight: 700;
   511→    text-transform: uppercase;
   512→    letter-spacing: .05em;
   513→    color: var(--text-3);
   514→    padding: 10px 14px;
   515→    border-bottom: 1px solid var(--border);
   516→    background: #f8fafc;
   517→    white-space: nowrap;
   518→}
   519→.admin-table tbody td {
   520→    padding: 11px 14px;
   521→    border-bottom: 1px solid #f1f5f9;
   522→    color: var(--text-2);
   523→    vertical-align: middle;
   524→}
   525→.admin-table tbody tr:last-child td { border-bottom: none; }
   526→.admin-table tbody tr:hover td { background: #f8fafc; }
   527→.admin-table .fw-med { font-weight: 600; color: var(--text); }
   528→.admin-table .mono { font-family: "SFMono-Regular", Consolas, monospace; font-size: 11.5px; }
   529→
   530→/* ===================== BADGES ===================== */
   531→.status-badge {
   532→    display: inline-flex;
   533→    align-items: center;
   534→    gap: 4px;
   535→    padding: 3px 9px;
   536→    border-radius: 20px;
   537→    font-size: 11.5px;
   538→    font-weight: 600;
   539→    white-space: nowrap;
   540→}
   541→.status-badge.paye    { background: var(--success-bg); color: var(--success); }
   542→.status-badge.attente { background: var(--warning-bg); color: var(--warning); }
   543→.status-badge.echec   { background: var(--danger-bg);  color: var(--danger); }
   544→.status-badge.info    { background: var(--accent-light); color: var(--accent); }
   545→
   546→/* ===================== PROGRESS ===================== */
   547→.progress-bar-wrap {
   548→    display: flex;
   549→    align-items: center;
   550→    gap: 10px;
   551→}
   552→.progress-track {
   553→    flex: 1;
   554→    height: 6px;
   555→    background: #e2e8f0;
   556→    border-radius: 3px;
   557→    overflow: hidden;
   558→}
   559→.progress-fill {
   560→    height: 100%;
   561→    background: linear-gradient(90deg, var(--accent) 0%, var(--accent-mid) 100%);
   562→    border-radius: 3px;
   563→    transition: width .5s ease;
   564→}
   565→.progress-pct {
   566→    font-size: 11px;
   567→    font-weight: 600;
   568→    color: var(--text-2);
   569→    width: 32px;
   570→    text-align: right;
   571→    flex-shrink: 0;
   572→}
   573→
   574→/* ===================== CHART SECTION ===================== */
   575→.chart-section {
   576→    background: var(--surface);
   577→    border: 1px solid var(--border);
   578→    border-radius: var(--radius);
   579→    box-shadow: var(--shadow-sm);
   580→    overflow: hidden;
   581→}
   582→.chart-container { position: relative; }
   583→
   584→/* ===================== FILTER BAR ===================== */
   585→.filter-bar {
   586→    background: var(--surface);
   587→    border: 1px solid var(--border);
   588→    border-radius: var(--radius);
   589→    padding: 14px 18px;
   590→    margin-bottom: 20px;
   591→    box-shadow: var(--shadow-sm);
   592→}
   593→
   594→/* ===================== EMPTY STATE ===================== */
   595→.empty-state {
   596→    text-align: center;
   597→    padding: 40px 20px;
   598→    color: var(--text-3);
   599→}
   600→.empty-state i { font-size: 36px; opacity: .4; margin-bottom: 8px; display: block; }
   601→.empty-state p { font-size: 13px; margin: 0; }
   602→
   603→/* ===================== DIVIDER ===================== */
   604→.section-divider {
   605→    height: 1px;
   606→    background: var(--border);
   607→    margin: 24px 0;
   608→}
   609→
   610→/* ===================== RESPONSIVE ===================== */
   611→@media (max-width: 768px) {
   612→    .admin-sidebar { width: var(--sidebar-collapsed-w); }
   613→    .admin-sidebar .sidebar-brand,
   614→    .admin-sidebar .nav-group-label,
   615→    .admin-sidebar .sidebar-link span,
   616→    .admin-sidebar .sidebar-link .nav-arrow,
   617→    .admin-sidebar .user-info,
   618→    .admin-sidebar .signout-text { display: none !important; }
   619→    .admin-main { margin-left: var(--sidebar-collapsed-w); }
   620→    .admin-content { padding: 16px; }
   621→    .stat-grid { grid-template-columns: repeat(2, 1fr); }
   622→    .finance-grid { grid-template-columns: 1fr; }
   623→    .page-header { flex-direction: column; align-items: flex-start; }
   624→}
   625→
   626→@media (max-width: 480px) {
   627→    .stat-grid { grid-template-columns: 1fr; }
   628→    .admin-content { padding: 12px; }
   629→}
   630→

arguments.content:
/* =============================================
   Admin Panel — Lycée Étoile Brillante
   Premium redesign
   ============================================= */

@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap');

:root {
    --sidebar-w: 260px;
    --sidebar-collapsed-w: 68px;
    --topbar-h: 62px;

    /* Sidebar palette */
    --sb-bg: #0d1b3e;
    --sb-bg2: #0a1530;
    --sb-accent: #2563eb;
    --sb-text: rgba(255,255,255,.65);
    --sb-text-active: #fff;
    --sb-hover-bg: rgba(255,255,255,.07);
    --sb-active-bg: rgba(37,99,235,.28);
    --sb-active-bar: #60a5fa;
    --sb-border: rgba(255,255,255,.06);

    /* Content palette */
    --bg: #f0f4f8;
    --surface: #ffffff;
    --border: #e2e8f0;
    --text: #0f172a;
    --text-2: #475569;
    --text-3: #94a3b8;

    /* Accents */
    --blue:   #2563eb;
    --blue-bg: #dbeafe;
    --green:  #16a34a;
    --green-bg: #dcfce7;
    --orange: #ea580c;
    --orange-bg: #ffedd5;
    --red:    #dc2626;
    --red-bg: #fee2e2;
    --purple: #7c3aed;
    --purple-bg: #ede9fe;
    --teal:   #0d9488;
    --teal-bg: #ccfbf1;
    --yellow: #d97706;
    --yellow-bg: #fef3c7;

    --radius: 12px;
    --radius-sm: 8px;
    --shadow-sm: 0 1px 3px rgba(0,0,0,.06), 0 1px 2px rgba(0,0,0,.04);
    --shadow:    0 4px 6px -1px rgba(0,0,0,.07), 0 2px 4px -1px rgba(0,0,0,.04);
    --shadow-md: 0 10px 25px -5px rgba(0,0,0,.10), 0 4px 10px -5px rgba(0,0,0,.04);
    --shadow-lg: 0 20px 40px -10px rgba(0,0,0,.14);
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

body.admin-body {
    background: var(--bg);
    font-family: 'Inter', -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
    color: var(--text);
    font-size: 14px;
    line-height: 1.55;
    -webkit-font-smoothing: antialiased;
}

/* ===================================================
   LAYOUT
=================================================== */
.admin-wrapper { display: flex; min-height: 100vh; }

/* ===================================================
   SIDEBAR
=================================================== */
.admin-sidebar {
    width: var(--sidebar-w);
    min-height: 100vh;
    background: var(--sb-bg);
    display: flex;
    flex-direction: column;
    position: fixed;
    top: 0; left: 0;
    z-index: 400;
    transition: width .22s cubic-bezier(.4,0,.2,1);
    overflow: hidden;
    box-shadow: 4px 0 24px rgba(0,0,0,.18);
}
.admin-sidebar::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 200px;
    background: radial-gradient(ellipse at 30% 0%, rgba(37,99,235,.25) 0%, transparent 70%);
    pointer-events: none;
}

.admin-sidebar.collapsed { width: var(--sidebar-collapsed-w); }
.admin-sidebar.collapsed .sidebar-brand,
.admin-sidebar.collapsed .nav-group-label,
.admin-sidebar.collapsed .sidebar-link span,
.admin-sidebar.collapsed .sidebar-link .nav-arrow,
.admin-sidebar.collapsed .user-info,
.admin-sidebar.collapsed .signout-text { display: none !important; }

/* Logo / Header */
.sidebar-header {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 22px 16px 18px;
    border-bottom: 1px solid var(--sb-border);
    text-decoration: none;
    flex-shrink: 0;
    position: relative;
    z-index: 1;
}
.sidebar-logo {
    width: 36px; height: 36px;
    background: rgba(255,255,255,.12);
    border-radius: 10px;
    padding: 4px;
    flex-shrink: 0;
    transition: background .2s;
    border: 1px solid rgba(255,255,255,.1);
}
.sidebar-header:hover .sidebar-logo { background: rgba(255,255,255,.2); }
.sidebar-brand { display: flex; flex-direction: column; min-width: 0; }
.brand-main {
    font-size: 13px; font-weight: 700;
    color: #fff; letter-spacing: .01em;
    white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.brand-sub {
    font-size: 10px; color: rgba(255,255,255,.38);
    letter-spacing: .08em; text-transform: uppercase;
}

/* Nav */
.sidebar-nav {
    flex: 1;
    padding: 10px 10px;
    overflow-y: auto; overflow-x: hidden;
    position: relative; z-index: 1;
}
.sidebar-nav::-webkit-scrollbar { width: 3px; }
.sidebar-nav::-webkit-scrollbar-thumb { background: rgba(255,255,255,.12); border-radius: 2px; }

.nav-group-label {
    font-size: 9.5px; font-weight: 700;
    text-transform: uppercase; letter-spacing: .1em;
    color: rgba(255,255,255,.25);
    padding: 16px 10px 6px;
    white-space: nowrap;
    display: block;
}

.sidebar-link {
    display: flex; align-items: center; gap: 10px;
    padding: 9px 10px;
    border-radius: var(--radius-sm);
    color: var(--sb-text);
    text-decoration: none;
    font-size: 13px; font-weight: 500;
    transition: background .15s, color .15s;
    margin-bottom: 2px;
    white-space: nowrap;
    position: relative;
}
.sidebar-link .nav-icon {
    font-size: 15px; width: 22px; text-align: center;
    flex-shrink: 0; transition: transform .15s;
}
.sidebar-link .nav-arrow { margin-left: auto; font-size: 10px; opacity: .4; }
.sidebar-link:hover { background: var(--sb-hover-bg); color: var(--sb-text-active); }
.sidebar-link:hover .nav-icon { transform: translateX(1px); }
.sidebar-link.active {
    background: var(--sb-active-bg);
    color: var(--sb-text-active);
    font-weight: 600;
}
.sidebar-link.active::before {
    content: '';
    position: absolute;
    left: 0; top: 7px; bottom: 7px;
    width: 3px;
    background: var(--sb-active-bar);
    border-radius: 0 3px 3px 0;
}

/* Footer */
.sidebar-footer {
    padding: 10px 10px 14px;
    border-top: 1px solid var(--sb-border);
    flex-shrink: 0;
    position: relative; z-index: 1;
}
.sidebar-user {
    display: flex; align-items: center; gap: 10px;
    padding: 8px 10px;
    border-radius: var(--radius-sm);
    background: rgba(255,255,255,.06);
    margin-bottom: 6px;
    overflow: hidden;
    border: 1px solid rgba(255,255,255,.05);
}
.user-avatar {
    width: 30px; height: 30px;
    background: linear-gradient(135deg, #2563eb, #1d4ed8);
    border-radius: 8px;
    display: flex; align-items: center; justify-content: center;
    font-size: 13px; color: #fff; flex-shrink: 0;
}
.user-info { min-width: 0; }
.user-name {
    font-size: 11.5px; font-weight: 600;
    color: rgba(255,255,255,.9);
    white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.user-role { font-size: 10px; color: rgba(255,255,255,.35); letter-spacing: .03em; }

.sidebar-signout {
    display: flex; align-items: center; gap: 8px;
    width: 100%; padding: 8px 10px;
    background: none; border: none; border-radius: var(--radius-sm);
    color: rgba(255,255,255,.38);
    font-size: 12px; font-family: inherit; cursor: pointer;
    transition: background .15s, color .15s; white-space: nowrap;
}
.sidebar-signout:hover { background: rgba(239,68,68,.12); color: #fca5a5; }

/* ===================================================
   MAIN
=================================================== */
.admin-main {
    margin-left: var(--sidebar-w);
    flex: 1; min-width: 0;
    display: flex; flex-direction: column;
    transition: margin-left .22s cubic-bezier(.4,0,.2,1);
}
.admin-sidebar.collapsed ~ .admin-main { margin-left: var(--sidebar-collapsed-w); }

/* ===================================================
   TOPBAR
=================================================== */
.admin-topbar {
    height: var(--topbar-h);
    background: var(--surface);
    border-bottom: 1px solid var(--border);
    display: flex; align-items: center;
    padding: 0 28px; gap: 14px;
    position: sticky; top: 0; z-index: 200;
    box-shadow: 0 1px 0 var(--border), var(--shadow-sm);
}
.topbar-toggle {
    background: none; border: none;
    font-size: 18px; color: var(--text-3); cursor: pointer;
    padding: 7px 8px; border-radius: var(--radius-sm);
    transition: background .15s, color .15s; line-height: 1; flex-shrink: 0;
}
.topbar-toggle:hover { background: var(--bg); color: var(--text); }

.topbar-breadcrumb {
    display: flex; align-items: center; gap: 6px; flex: 1; min-width: 0;
}
.breadcrumb-item { font-size: 13px; color: var(--text-3); white-space: nowrap; }
.breadcrumb-item.current { font-weight: 600; color: var(--text); }
.breadcrumb-sep { color: var(--text-3); font-size: 11px; }

.topbar-right { display: flex; align-items: center; gap: 10px; flex-shrink: 0; }
.topbar-badge {
    display: inline-flex; align-items: center; gap: 5px;
    padding: 4px 12px;
    background: #eff6ff;
    border: 1px solid #bfdbfe;
    border-radius: 20px;
    font-size: 11.5px; font-weight: 700;
    color: var(--blue);
    letter-spacing: .02em;
}

/* ===================================================
   CONTENT AREA
=================================================== */
.admin-content { flex: 1; padding: 28px; }

.page-header {
    display: flex; align-items: flex-end;
    justify-content: space-between; gap: 12px;
    margin-bottom: 28px; flex-wrap: wrap;
}
.page-title {
    font-size: 22px; font-weight: 800;
    color: var(--text); line-height: 1.25; letter-spacing: -.02em;
}
.page-subtitle { font-size: 13px; color: var(--text-2); margin-top: 4px; }

/* ===================================================
   STAT CARDS — gradient style
=================================================== */
.stat-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(210px, 1fr));
    gap: 16px;
    margin-bottom: 24px;
}

.stat-card {
    border-radius: var(--radius);
    padding: 22px 20px 18px;
    display: flex; flex-direction: column; gap: 14px;
    transition: transform .2s, box-shadow .2s;
    position: relative; overflow: hidden;
    color: #fff;
}
.stat-card:hover { transform: translateY(-2px); box-shadow: var(--shadow-md); }

/* Sheen overlay */
.stat-card::before {
    content: '';
    position: absolute; top: -40%; right: -20%;
    width: 160px; height: 160px;
    background: rgba(255,255,255,.12);
    border-radius: 50%;
    pointer-events: none;
}
.stat-card::after {
    content: '';
    position: absolute; bottom: -30%; left: 10%;
    width: 100px; height: 100px;
    background: rgba(255,255,255,.07);
    border-radius: 50%;
    pointer-events: none;
}

.stat-card.blue   { background: linear-gradient(135deg, #2563eb 0%, #1d4ed8 100%); box-shadow: 0 8px 20px rgba(37,99,235,.35); }
.stat-card.teal   { background: linear-gradient(135deg, #0d9488 0%, #0f766e 100%); box-shadow: 0 8px 20px rgba(13,148,136,.35); }
.stat-card.purple { background: linear-gradient(135deg, #7c3aed 0%, #6d28d9 100%); box-shadow: 0 8px 20px rgba(124,58,237,.35); }
.stat-card.orange { background: linear-gradient(135deg, #ea580c 0%, #c2410c 100%); box-shadow: 0 8px 20px rgba(234,88,12,.35); }
.stat-card.green  { background: linear-gradient(135deg, #16a34a 0%, #15803d 100%); box-shadow: 0 8px 20px rgba(22,163,74,.35); }
.stat-card.red    { background: linear-gradient(135deg, #dc2626 0%, #b91c1c 100%); box-shadow: 0 8px 20px rgba(220,38,38,.35); }

.stat-row { display: flex; align-items: flex-start; justify-content: space-between; }
.stat-icon {
    width: 42px; height: 42px;
    background: rgba(255,255,255,.2);
    border-radius: 10px;
    display: flex; align-items: center; justify-content: center;
    font-size: 19px; flex-shrink: 0;
    backdrop-filter: blur(4px);
}
.stat-value {
    font-size: 30px; font-weight: 800;
    line-height: 1; letter-spacing: -.03em;
    color: #fff;
}
.stat-label {
    font-size: 12px; font-weight: 500;
    color: rgba(255,255,255,.75);
    margin-top: 4px;
}
.stat-trend {
    font-size: 11.5px; color: rgba(255,255,255,.65);
    display: flex; align-items: center; gap: 4px;
}
.stat-trend a { color: rgba(255,255,255,.65); text-decoration: none; }
.stat-trend a:hover { color: #fff; text-decoration: underline; }

/* ===================================================
   FINANCE CARDS
=================================================== */
.finance-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
    gap: 14px;
    margin-bottom: 24px;
}
.finance-card {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: var(--radius);
    padding: 18px 20px;
    display: flex; align-items: center; gap: 16px;
    transition: box-shadow .2s, transform .2s;
    box-shadow: var(--shadow-sm);
}
.finance-card:hover { box-shadow: var(--shadow); transform: translateY(-1px); }

.finance-icon {
    width: 50px; height: 50px; border-radius: 12px;
    display: flex; align-items: center; justify-content: center;
    font-size: 21px; flex-shrink: 0;
}
.finance-icon.green  { background: var(--green-bg); color: var(--green); }
.finance-icon.orange { background: var(--orange-bg); color: var(--orange); }
.finance-icon.red    { background: var(--red-bg);    color: var(--red); }

.finance-value { font-size: 21px; font-weight: 800; line-height: 1.2; letter-spacing: -.02em; }
.finance-value.green  { color: var(--green); }
.finance-value.orange { color: var(--orange); }
.finance-value.red    { color: var(--red); }
.finance-label { font-size: 11.5px; color: var(--text-2); margin-top: 3px; font-weight: 500; }

/* ===================================================
   CARDS
=================================================== */
.admin-card {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: var(--radius);
    overflow: hidden;
    box-shadow: var(--shadow-sm);
    transition: box-shadow .2s;
}
.admin-card:hover { box-shadow: var(--shadow); }
.admin-card + .admin-card { margin-top: 16px; }

.admin-card-header {
    padding: 16px 20px;
    border-bottom: 1px solid var(--border);
    display: flex; align-items: center;
    justify-content: space-between; gap: 8px;
    background: #fafbfc;
}
.admin-card-header h6 {
    font-size: 13px; font-weight: 700;
    color: var(--text); margin: 0;
    display: flex; align-items: center; gap: 8px;
    letter-spacing: -.01em;
}
.admin-card-header h6 i { color: var(--blue); font-size: 14px; }
.admin-card-body { padding: 18px 20px; }

/* ===================================================
   TABLES
=================================================== */
.admin-table { width: 100%; border-collapse: collapse; font-size: 13px; }
.admin-table thead th {
    font-size: 10.5px; font-weight: 700;
    text-transform: uppercase; letter-spacing: .06em;
    color: var(--text-3);
    padding: 10px 16px;
    border-bottom: 1px solid var(--border);
    background: #f8fafc;
    white-space: nowrap;
}
.admin-table tbody td {
    padding: 12px 16px;
    border-bottom: 1px solid #f1f5f9;
    color: var(--text-2);
    vertical-align: middle;
}
.admin-table tbody tr:last-child td { border-bottom: none; }
.admin-table tbody tr:hover td { background: #f8fafc; }
.admin-table .fw-med { font-weight: 600; color: var(--text); }
.admin-table .mono {
    font-family: "SFMono-Regular", Consolas, "Liberation Mono", monospace;
    font-size: 11.5px; letter-spacing: .02em;
}

/* ===================================================
   BADGES
=================================================== */
.status-badge {
    display: inline-flex; align-items: center; gap: 4px;
    padding: 3px 10px; border-radius: 20px;
    font-size: 11px; font-weight: 700;
    white-space: nowrap; letter-spacing: .02em;
}
.status-badge.paye    { background: var(--green-bg);  color: var(--green); }
.status-badge.attente { background: var(--yellow-bg); color: var(--yellow); }
.status-badge.echec   { background: var(--red-bg);    color: var(--red); }
.status-badge.info    { background: var(--blue-bg);   color: var(--blue); }

/* ===================================================
   PROGRESS BAR
=================================================== */
.progress-bar-wrap { display: flex; align-items: center; gap: 10px; }
.progress-track {
    flex: 1; height: 5px;
    background: #e2e8f0; border-radius: 3px; overflow: hidden;
}
.progress-fill {
    height: 100%;
    background: linear-gradient(90deg, #2563eb 0%, #60a5fa 100%);
    border-radius: 3px;
    transition: width .6s cubic-bezier(.4,0,.2,1);
}
.progress-pct {
    font-size: 11px; font-weight: 700;
    color: var(--text-2); width: 34px; text-align: right; flex-shrink: 0;
}

/* ===================================================
   CHART
=================================================== */
.chart-container { position: relative; }

/* ===================================================
   FILTER BAR
=================================================== */
.filter-bar {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: var(--radius);
    padding: 14px 18px;
    margin-bottom: 20px;
    box-shadow: var(--shadow-sm);
}

/* ===================================================
   EMPTY STATE
=================================================== */
.empty-state {
    text-align: center; padding: 48px 20px;
    color: var(--text-3);
}
.empty-state i { font-size: 38px; opacity: .3; margin-bottom: 10px; display: block; }
.empty-state p { font-size: 13px; margin: 0; font-weight: 500; }

/* ===================================================
   WELCOME BANNER (dashboard top)
=================================================== */
.welcome-banner {
    background: linear-gradient(135deg, #0d1b3e 0%, #1e3a8a 60%, #1d4ed8 100%);
    border-radius: var(--radius);
    padding: 28px 32px;
    margin-bottom: 24px;
    display: flex; align-items: center;
    justify-content: space-between; gap: 16px;
    flex-wrap: wrap;
    position: relative; overflow: hidden;
    box-shadow: 0 8px 32px rgba(13,27,62,.35);
}
.welcome-banner::before {
    content: '';
    position: absolute; top: -50%; right: -10%;
    width: 300px; height: 300px;
    background: radial-gradient(circle, rgba(96,165,250,.25) 0%, transparent 70%);
    pointer-events: none;
}
.welcome-banner::after {
    content: '';
    position: absolute; bottom: -60%; left: 5%;
    width: 200px; height: 200px;
    background: radial-gradient(circle, rgba(255,255,255,.06) 0%, transparent 70%);
    pointer-events: none;
}
.welcome-text { position: relative; z-index: 1; }
.welcome-title {
    font-size: 20px; font-weight: 800;
    color: #fff; letter-spacing: -.02em; margin: 0 0 5px;
}
.welcome-sub { font-size: 13px; color: rgba(255,255,255,.6); margin: 0; }
.welcome-actions { position: relative; z-index: 1; display: flex; gap: 8px; flex-wrap: wrap; }
.welcome-btn {
    display: inline-flex; align-items: center; gap: 6px;
    padding: 8px 16px; border-radius: 8px;
    font-size: 12.5px; font-weight: 600; text-decoration: none;
    transition: background .15s, transform .1s;
    white-space: nowrap;
}
.welcome-btn:hover { transform: translateY(-1px); }
.welcome-btn.light {
    background: rgba(255,255,255,.15); color: #fff;
    border: 1px solid rgba(255,255,255,.2);
    backdrop-filter: blur(4px);
}
.welcome-btn.light:hover { background: rgba(255,255,255,.22); }
.welcome-btn.white {
    background: #fff; color: #1e3a8a;
    border: 1px solid rgba(255,255,255,.3);
}
.welcome-btn.white:hover { background: #f0f9ff; }

/* ===================================================
   DIVIDER
=================================================== */
.section-divider { height: 1px; background: var(--border); margin: 24px 0; }

/* ===================================================
   RESPONSIVE
=================================================== */
@media (max-width: 900px) {
    .admin-sidebar { width: var(--sidebar-collapsed-w); }
    .admin-sidebar .sidebar-brand,
    .admin-sidebar .nav-group-label,
    .admin-sidebar .sidebar-link span,
    .admin-sidebar .sidebar-link .nav-arrow,
    .admin-sidebar .user-info,
    .admin-sidebar .signout-text { display: none !important; }
    .admin-main { margin-left: var(--sidebar-collapsed-w); }
    .admin-content { padding: 18px; }
    .welcome-banner { padding: 20px 22px; }
}

@media (max-width: 600px) {
    .stat-grid { grid-template-columns: 1fr 1fr; }
    .finance-grid { grid-template-columns: 1fr; }
    .admin-content { padding: 14px; }
}
@media (max-width: 400px) {
    .stat-grid { grid-template-columns: 1fr; }
}

